import PyPDF2


class PDFHandler:
    def __init__(self, filepaths):
        self.filepaths = filepaths
        self.readers = self._create_readers(filepaths)

    def _create_readers(self, filepaths):
        return [PyPDF2.PdfReader(fp) for fp in filepaths]

    def merge_pdfs(self, output_filepath):
        pdf_writer = PyPDF2.PdfWriter()

        for reader in self.readers:
            for page in self._iterate_pages(reader):
                pdf_writer.add_page(page)

        self._write_pdf(pdf_writer, output_filepath)
        return f"Merged PDFs saved at {output_filepath}"

    def _iterate_pages(self, reader):
        for page_num in range(len(reader.pages)):
            yield reader.pages[page_num]

    def _write_pdf(self, pdf_writer, output_filepath):
        with open(output_filepath, 'wb') as out:
            pdf_writer.write(out)

    def extract_text_from_pdfs(self):
        pdf_texts = []
        for reader in self.readers:
            for page in self._iterate_pages(reader):
                pdf_texts.append(self._extract_page_text(page))
        return pdf_texts

    def _extract_page_text(self, page):
        return page.extract_text()
